<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { HttpStaffApi } from "../features/staff/api";
import type { QuestionBankSummary, QuestionDraft, QuestionImportPreview, QuestionSummary, Subject } from "../features/staff/types";
import { messageFrom, safeHtmlPreview } from "../features/staff/helpers";
import { subjectOptionLabel } from "../features/staff/master-data-policies";
import ScopeSwitcher from "../components/ScopeSwitcher.vue";

const api = new HttpStaffApi();
const items = ref<readonly QuestionSummary[]>([]);
const banks = ref<readonly QuestionBankSummary[]>([]);
const subjects = ref<readonly Subject[]>([]);
const query = ref("");
const loading = ref(true);
const error = ref("");
const selected = ref<QuestionDraft | null>(null);
const saving = ref(false);
const bankSaving = ref(false);
const showBankForm = ref(false);
const showImportForm = ref(false);
const bankForm = ref({ subjectId: "", name: "" });
const questionImportBankId = ref("");
const questionImportCsv = ref("");
const questionImportFileName = ref("");
const questionImportPreview = ref<QuestionImportPreview | null>(null);
const questionImportBusy = ref(false);
const questionImportMessage = ref("");
const report = ref<{ isReady: boolean; issues: readonly { severity: string; message: string; fieldPath: string }[] } | null>(null);
const form = ref({ questionBankId: "", type: "SINGLE_CHOICE", stimulusHtml: "", promptHtml: "", explanationHtml: "", options: [{ contentHtml: "", isCorrect: false }, { contentHtml: "", isCorrect: false }], statements: [{ statementHtml: "", correctValue: true }, { statementHtml: "", correctValue: false }, { statementHtml: "", correctValue: false }] });
const dirty = computed(() => Boolean(selected.value) && !saving.value);

async function load(): Promise<void> { loading.value = true; error.value = ""; try { const [questionPage, bankPage, subjectPage] = await Promise.all([api.questions(query.value), api.questionBanks(), api.teacherSubjects()]); items.value = questionPage.items; banks.value = bankPage.items; subjects.value = subjectPage.items; } catch (cause) { error.value = messageFrom(cause, "Bank soal belum tersedia."); } finally { loading.value = false; } }
async function createBank(): Promise<void> { bankSaving.value = true; error.value = ""; try { const bank = await api.createQuestionBank({ subjectId: bankForm.value.subjectId, name: bankForm.value.name }); banks.value = [bank, ...banks.value]; bankForm.value.name = ""; showBankForm.value = false; } catch (cause) { error.value = messageFrom(cause, "Bank soal belum dapat dibuat."); } finally { bankSaving.value = false; } }
async function readQuestionImportFile(event: Event): Promise<void> { const file = (event.target as HTMLInputElement).files?.[0]; if (!file) return; if (file.size > 1024 * 1024) { questionImportMessage.value = "File CSV maksimal 1 MiB."; return; } questionImportCsv.value = await file.text(); questionImportFileName.value = file.name; questionImportPreview.value = null; questionImportMessage.value = "File siap dipratinjau."; }
function resetQuestionImportPreview(): void { if (!questionImportPreview.value) return; questionImportPreview.value = null; questionImportMessage.value = "Bank tujuan berubah. Buat preview baru sebelum import."; }
function downloadQuestionImportTemplate(): void { const headers = ["type", "stimulus", "prompt", "explanation", ...Array.from({ length: 10 }, (_, index) => `option_${index + 1}`), ...Array.from({ length: 10 }, (_, index) => `option_${index + 1}_correct`), ...Array.from({ length: 3 }, (_, index) => `statement_${index + 1}`), ...Array.from({ length: 3 }, (_, index) => `statement_${index + 1}_correct`)]; const makeRow = (values: Record<string, string>) => headers.map((field) => values[field] ?? "").join(","); const csv = [headers.join(","), makeRow({ type: "SINGLE_CHOICE", stimulus: "Bacalah stimulus ini.", prompt: "Pilih jawaban yang tepat.", option_1: "Pilihan A", option_1_correct: "BENAR", option_2: "Pilihan B", option_2_correct: "SALAH" }), makeRow({ type: "MULTIPLE_RESPONSE", stimulus: "Bacalah stimulus ini.", prompt: "Pilih semua jawaban yang tepat.", option_1: "Pilihan A", option_1_correct: "BENAR", option_2: "Pilihan B", option_2_correct: "SALAH", option_3: "Pilihan C", option_3_correct: "BENAR" }), makeRow({ type: "TRUE_FALSE", stimulus: "Bacalah stimulus ini.", statement_1: "Pernyataan pertama.", statement_1_correct: "BENAR", statement_2: "Pernyataan kedua.", statement_2_correct: "SALAH", statement_3: "Pernyataan ketiga.", statement_3_correct: "BENAR" })].join("\n"); const url = URL.createObjectURL(new Blob([csv], { type: "text/csv;charset=utf-8" })); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "template-import-soal.csv"; anchor.click(); URL.revokeObjectURL(url); }
async function previewQuestionImport(): Promise<void> { if (!questionImportBankId.value || !questionImportCsv.value) { questionImportMessage.value = "Pilih bank soal dan file CSV terlebih dahulu."; return; } questionImportBusy.value = true; questionImportMessage.value = "Server sedang memvalidasi soal…"; try { questionImportPreview.value = await api.previewQuestionImport(questionImportBankId.value, questionImportCsv.value); questionImportMessage.value = questionImportPreview.value.errorCount ? "Preview selesai. Perbaiki baris error sebelum import." : "Preview valid. Soal akan dibuat sebagai draft."; } catch (cause) { questionImportMessage.value = messageFrom(cause, "Preview import belum dapat dibuat."); } finally { questionImportBusy.value = false; } }
async function commitQuestionImport(): Promise<void> { const preview = questionImportPreview.value; if (!preview || preview.errorCount || questionImportBusy.value) return; const bankName = banks.value.find((bank) => bank.id === questionImportBankId.value)?.name ?? "bank yang dipilih"; if (!window.confirm(`Import ${preview.validCount} soal sebagai draft ke bank ${bankName}?`)) return; questionImportBusy.value = true; questionImportMessage.value = "Server sedang membuat draft soal…"; try { const result = await api.commitQuestionImport(questionImportBankId.value, questionImportCsv.value, preview.sourceHash); questionImportMessage.value = `${result.createdCount} soal berhasil dibuat sebagai draft.`; questionImportPreview.value = null; questionImportCsv.value = ""; questionImportFileName.value = ""; await load(); } catch (cause) { questionImportMessage.value = messageFrom(cause, "Import soal belum dapat diselesaikan."); } finally { questionImportBusy.value = false; } }
function bankSubjectLabel(subjectId: string): string { const subject = subjects.value.find((item) => item.id === subjectId); return subject ? subjectOptionLabel(subject) : `Mata pelajaran #${subjectId}`; }
function open(item?: QuestionSummary): void {
  report.value = null;
  if (!item) { selected.value = { id: "new", questionId: "new", questionBank: { id: "", name: "Bank baru", subjectId: "" }, revisionNo: 1, type: "SINGLE_CHOICE", status: "DRAFT", stimulusHtml: "", promptHtml: "", explanationHtml: "", options: [], statements: [], updatedAt: "" }; form.value = { ...form.value, questionBankId: "", type: "SINGLE_CHOICE", stimulusHtml: "", promptHtml: "", explanationHtml: "" }; return; }
  void api.question(item.id).then((draft) => { selected.value = draft; form.value = { questionBankId: draft.questionBank.id, type: draft.type, stimulusHtml: draft.stimulusHtml, promptHtml: draft.promptHtml ?? "", explanationHtml: draft.explanationHtml ?? "", options: draft.options.map((option) => ({ contentHtml: option.contentHtml, isCorrect: option.isCorrect })), statements: draft.statements.map((statement) => ({ statementHtml: statement.statementHtml, correctValue: statement.correctValue })) }; }).catch((cause) => { error.value = messageFrom(cause); });
}
function close(): void { selected.value = null; report.value = null; }
function addOption(): void { if (form.value.options.length < 10) form.value.options.push({ contentHtml: "", isCorrect: false }); }
function addStatement(): void { if (form.value.statements.length < 3) form.value.statements.push({ statementHtml: "", correctValue: false }); }
async function save(): Promise<void> {
  if (!selected.value) return; saving.value = true; error.value = "";
  try {
    const payload = { type: form.value.type, stimulusHtml: form.value.stimulusHtml, promptHtml: form.value.type === "TRUE_FALSE" ? null : form.value.promptHtml || null, explanationHtml: form.value.explanationHtml || null, options: form.value.type === "TRUE_FALSE" ? [] : form.value.options.map((item, index) => ({ position: index + 1, ...item })), statements: form.value.type === "TRUE_FALSE" ? form.value.statements.map((item, index) => ({ position: index + 1, ...item })) : [] };
    selected.value = selected.value.id === "new" ? await api.createQuestion({ questionBankId: form.value.questionBankId, ...payload }) : await api.updateQuestion(selected.value.id, payload, selected.value.updatedAt);
    report.value = null;
    await load();
  } catch (cause) { error.value = messageFrom(cause); } finally { saving.value = false; }
}
async function validate(): Promise<void> { if (!selected.value || selected.value.id === "new") { report.value = { isReady: false, issues: [{ severity: "ERROR", message: "Simpan draft sebelum validasi.", fieldPath: "" }] }; return; } try { report.value = await api.validateQuestion(selected.value.id); } catch (cause) { error.value = messageFrom(cause); } }
async function publish(): Promise<void> { if (!selected.value || !report.value?.isReady) return; if (!window.confirm("Publish revision soal? Setelah publish, revisi menjadi immutable.")) return; try { selected.value = await api.publishQuestion(selected.value.id, selected.value.updatedAt); await load(); } catch (cause) { error.value = messageFrom(cause); } }
onMounted(() => { void load(); });
</script>

<template>
  <header class="page-heading between"><div><p class="eyebrow">Guru · Authoring</p><h1>Bank Soal</h1><p class="muted">Buat bank dan validasi tiga tipe soal dengan answer key hanya di area staff.</p></div><div class="stack"><button class="btn-secondary" type="button" @click="showBankForm = !showBankForm">Buat bank</button><button class="btn-secondary" type="button" @click="showImportForm = !showImportForm">Import soal</button><button class="btn-primary" type="button" @click="open()">Buat soal</button></div></header>
  <section v-if="showBankForm" class="card bank-form"><form class="form-grid" @submit.prevent="createBank"><label>Mata pelajaran<select v-model="bankForm.subjectId" required><option value="" disabled>Pilih mata pelajaran</option><option v-for="subject in subjects" :key="subject.id" :value="subject.id">{{ subjectOptionLabel(subject) }}</option></select><small v-if="subjects.length === 0" class="muted">Belum ada mata pelajaran yang ditugaskan. Minta admin mengatur scope guru.</small></label><label>Nama bank<input v-model="bankForm.name" maxlength="200" required /></label><button class="btn-primary" type="submit" :disabled="bankSaving || subjects.length === 0 || !bankForm.subjectId">{{ bankSaving ? "Menyimpan…" : "Simpan bank" }}</button></form></section>
  <section v-if="showImportForm" class="card import-panel" aria-labelledby="question-import-title"><div class="between"><div><h2 id="question-import-title">Import soal CSV</h2><p class="muted">Soal valid dibuat sebagai draft. Server tidak menyimpan file setelah preview.</p></div><button class="btn-quiet" type="button" @click="showImportForm = false">Tutup</button></div><div class="form-grid import-fields"><label>Bank tujuan<select v-model="questionImportBankId" :disabled="questionImportBusy" required @change="resetQuestionImportPreview"><option value="" disabled>Pilih bank soal</option><option v-for="bank in banks" :key="bank.id" :value="bank.id">{{ bank.name }} · {{ bankSubjectLabel(bank.subjectId) }}</option></select></label><label>File CSV<input type="file" accept=".csv,text/csv" :disabled="questionImportBusy" @change="readQuestionImportFile" /><small class="muted">Maksimal 300 soal atau 1 MiB. Kunci menerima BENAR/SALAH, TRUE/FALSE, atau 1/0.</small></label></div><details class="import-help"><summary>Petunjuk format CSV</summary><ul><li>Template berisi satu contoh untuk setiap tipe; hapus contoh sebelum menggantinya dengan soal Anda.</li><li><strong>SINGLE_CHOICE</strong> dan <strong>MULTIPLE_RESPONSE</strong> memakai <code>prompt</code>, kolom <code>option_*</code>, dan <code>option_*_correct</code>.</li><li><strong>TRUE_FALSE</strong> hanya memakai <code>stimulus</code>, tiga kolom <code>statement_*</code>, dan kunci masing-masing pernyataan.</li></ul></details><div class="import-actions"><button class="btn-quiet" type="button" @click="downloadQuestionImportTemplate">Unduh template CSV</button><button class="btn-secondary" type="button" :disabled="questionImportBusy || !questionImportCsv || !questionImportBankId" @click="previewQuestionImport">{{ questionImportBusy ? "Memproses…" : "Preview import" }}</button></div><p v-if="questionImportFileName" class="muted small-copy">File: {{ questionImportFileName }}</p><p v-if="questionImportMessage" class="alert alert-info" aria-live="polite">{{ questionImportMessage }}</p><template v-if="questionImportPreview"><div class="import-summary"><span>Total {{ questionImportPreview.totalRows }}</span><span>Valid {{ questionImportPreview.validCount }}</span><span :class="{ 'text-danger': questionImportPreview.errorCount > 0 }">Error {{ questionImportPreview.errorCount }}</span></div><div class="table-scroll import-preview-table"><table><caption class="sr-only">Preview import soal</caption><thead><tr><th>Baris</th><th>Tipe</th><th>Ringkasan</th><th>Status</th><th>Detail</th></tr></thead><tbody><tr v-for="row in questionImportPreview.rows" :key="row.rowNumber"><td>{{ row.rowNumber }}</td><td>{{ row.type ?? "—" }}</td><td>{{ row.label ?? "—" }}</td><td><span class="badge" :class="row.status === 'VALID' ? 'badge-success' : 'badge-warning'">{{ row.status === 'VALID' ? 'Valid' : 'Error' }}</span></td><td><span v-if="row.errors.length === 0">—</span><span v-for="item in row.errors" :key="`${item.field}-${item.code}`" class="import-error">{{ item.field }}: {{ item.message }}</span></td></tr></tbody></table></div><div class="import-actions"><button class="btn-primary" type="button" :disabled="questionImportBusy || questionImportPreview.errorCount > 0" @click="commitQuestionImport">Import {{ questionImportPreview.validCount }} soal</button></div></template></section>
  <ScopeSwitcher :dirty="dirty" />
  <div class="toolbar"><form class="search-form" @submit.prevent="load"><label class="sr-only" for="question-search">Cari soal</label><input id="question-search" v-model="query" placeholder="Cari stimulus, bank, atau tipe" /><button class="btn-secondary" type="submit">Cari</button></form><span class="muted">{{ items.length }} item</span></div>
  <div v-if="error" class="alert alert-error" role="alert">{{ error }}</div>
  <section class="card table-card"><div v-if="loading" class="table-state">Memuat bank soal…</div><div v-else-if="items.length === 0" class="table-state"><strong>Belum ada soal</strong><span class="muted">Buat draft pertama dari tombol di atas.</span></div><div v-else class="table-scroll"><table><caption class="sr-only">Daftar soal</caption><thead><tr><th>Preview</th><th>Type</th><th>Status</th><th>Updated</th><th></th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.bankName }}</strong><small>{{ safeHtmlPreview(item.label) }}</small></td><td>{{ item.type }}</td><td><span class="badge" :class="item.status === 'PUBLISHED' ? 'badge-success' : 'badge-warning'">{{ item.status }}</span></td><td>{{ item.updatedAt }}</td><td><button class="btn-quiet" type="button" @click="open(item)">Buka editor</button></td></tr></tbody></table></div></section>
  <div v-if="selected" class="overlay" role="dialog" aria-modal="true" aria-labelledby="question-editor-title"><section class="drawer"><div class="between"><div><p class="eyebrow">{{ selected.status }}</p><h2 id="question-editor-title">Editor soal</h2></div><button class="btn-quiet" type="button" @click="close">Tutup</button></div><form @submit.prevent="save"><div v-if="selected.id === 'new'" class="form-row"><label for="question-bank-id">Bank soal</label><select id="question-bank-id" v-model="form.questionBankId" required><option value="" disabled>Pilih bank soal</option><option v-for="bank in banks" :key="bank.id" :value="bank.id">{{ bank.name }} · {{ bankSubjectLabel(bank.subjectId) }}</option></select><small v-if="banks.length === 0" class="muted">Buat bank soal terlebih dahulu.</small></div><div class="form-row"><label for="question-type">Tipe soal</label><select id="question-type" v-model="form.type"><option value="SINGLE_CHOICE">Single choice · exact match</option><option value="MULTIPLE_RESPONSE">Multiple response · semua tepat</option><option value="TRUE_FALSE">True/False · tiga pernyataan</option></select></div><div class="form-row"><label for="stimulus">Stimulus</label><textarea id="stimulus" v-model="form.stimulusHtml" rows="4" required /></div><div v-if="form.type !== 'TRUE_FALSE'" class="form-row"><label for="prompt">Pertanyaan</label><textarea id="prompt" v-model="form.promptHtml" rows="3" required /></div><div v-if="form.type !== 'TRUE_FALSE'" class="child-editor"><div class="between"><h3>Opsi jawaban</h3><button class="btn-quiet" type="button" @click="addOption">Tambah opsi</button></div><div v-for="(option, index) in form.options" :key="index" class="child-row"><input v-model="option.contentHtml" :aria-label="`Isi opsi ${index + 1}`" required /><label><input v-model="option.isCorrect" type="checkbox" /> benar</label></div><p class="muted small-copy">Single choice harus tepat satu benar; multiple response minimal satu dan semua key harus tepat.</p></div><div v-else class="child-editor"><div class="between"><h3>Tiga pernyataan</h3><button class="btn-quiet" type="button" @click="addStatement">Tambah</button></div><div v-for="(statement, index) in form.statements" :key="index" class="child-row"><input v-model="statement.statementHtml" :aria-label="`Pernyataan ${index + 1}`" required /><select v-model="statement.correctValue" :aria-label="`Jawaban pernyataan ${index + 1}`"><option :value="true">Benar</option><option :value="false">Salah</option></select></div></div><div class="form-row"><label for="explanation">Penjelasan (opsional)</label><textarea id="explanation" v-model="form.explanationHtml" rows="3" /></div><div v-if="report" class="readiness" :class="report.isReady ? 'ready' : 'blocked'"><strong>{{ report.isReady ? 'Siap dipublish' : 'Belum siap dipublish' }}</strong><ul><li v-for="issue in report.issues" :key="`${issue.fieldPath}-${issue.message}`">{{ issue.severity }} · {{ issue.message }} <button v-if="issue.fieldPath" class="link-button" type="button">Buka field</button></li></ul></div><div class="editor-actions"><button class="btn-secondary" type="button" :disabled="saving" @click="validate">Validasi</button><button class="btn-primary" type="submit" :disabled="saving">{{ saving ? 'Menyimpan…' : 'Simpan draft' }}</button><button v-if="selected.status === 'DRAFT'" class="btn-secondary" type="button" :disabled="saving || !report?.isReady" @click="publish">Publish</button></div></form></section></div>
</template>

<style scoped>
.page-heading { align-items: flex-start; margin-bottom: 18px; }.page-heading h1 { margin: 0 0 6px; }.eyebrow { margin: 0 0 4px; color: var(--primary); font-weight: 700; }.toolbar { display: flex; justify-content: space-between; align-items: center; gap: 12px; margin: 16px 0; }.search-form { display: flex; gap: 8px; }.search-form input { min-height: 40px; min-width: min(360px, 55vw); }.table-card, .import-panel { padding: 20px; }.import-panel { margin-bottom: 18px; }.import-panel h2 { margin: 0 0 6px; }.import-fields { margin-top: 18px; }.import-fields label { display: grid; gap: 6px; }.import-fields select, .import-fields input { width: 100%; min-height: 40px; box-sizing: border-box; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px 10px; color: var(--text); background: var(--surface); }.import-help { margin-top: 16px; padding: 10px 12px; border: 1px solid var(--border); border-radius: 8px; color: var(--muted); }.import-help summary { color: var(--text); cursor: pointer; font-weight: 700; }.import-help ul { margin: 10px 0 0; padding-left: 20px; }.import-actions { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 16px; }.import-summary { display: flex; flex-wrap: wrap; gap: 8px; margin: 16px 0; }.import-summary span { padding: 8px 10px; border-radius: 8px; background: var(--canvas); font-size: .86rem; }.import-preview-table { margin-top: 16px; }.import-error { display: block; margin-bottom: 4px; color: var(--danger); font-size: .85rem; }.text-danger { color: var(--danger); }.table-scroll { overflow-x: auto; } table { width: 100%; border-collapse: collapse; } th, td { padding: 12px 10px; text-align: left; border-bottom: 1px solid var(--border); vertical-align: top; } th { color: var(--muted); font-size: .8rem; } td small { display: block; color: var(--subtle); margin-top: 4px; }.table-state { display: grid; gap: 6px; justify-items: center; padding: 42px 12px; }.badge { display: inline-flex; padding: 4px 8px; border-radius: 99px; background: var(--primary-soft); color: var(--primary); font-size: .78rem; font-weight: 700; }.badge-success { color: var(--success); background: var(--success-soft); }.badge-warning { color: var(--warning); background: var(--warning-soft); }.overlay { position: fixed; inset: 0; z-index: 20; display: flex; justify-content: flex-end; background: rgb(2 6 23 / 45%); }.drawer { width: min(680px, 100%); height: 100%; overflow: auto; padding: 24px; background: var(--surface); box-shadow: var(--shadow); }.form-row textarea, .form-row select { width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px 10px; color: var(--text); background: var(--surface); }.child-editor { margin: 16px 0; padding: 14px; border: 1px solid var(--border); border-radius: 10px; }.child-editor h3 { margin: 0; }.child-row { display: grid; grid-template-columns: 1fr auto; gap: 8px; align-items: center; margin: 10px 0; }.child-row input:not([type='checkbox']), .child-row select { min-height: 40px; width: 100%; border: 1px solid var(--border-strong); border-radius: 8px; padding: 8px; background: var(--surface); color: var(--text); }.readiness { margin: 16px 0; padding: 12px; border-radius: 8px; }.readiness.ready { color: var(--success); background: var(--success-soft); }.readiness.blocked { color: var(--danger); background: var(--danger-soft); }.readiness ul { margin-bottom: 0; padding-left: 20px; }.link-button { border: 0; min-height: auto; padding: 0; color: inherit; background: transparent; text-decoration: underline; }.editor-actions { display: flex; flex-wrap: wrap; gap: 8px; }.small-copy { font-size: .84rem; }.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }
@media (max-width: 600px) { .page-heading, .toolbar { display: grid; align-items: stretch; }.search-form input { min-width: 0; flex: 1; } .drawer { padding: 18px 14px; } }
</style>
